          "kind": "WRITE",
          "points": 1.5,
          "prompt": "<div class=\"ml-en\"><p><b>Question 5 (1.5 points)</b> — <b>Task 2, Q5</b>: On the <b>detail</b> route, display all the student information: <b>Id</b>, <b>Name</b>, <b>DateOfBirth</b>, <b>Gender</b>, <b>Class</b>, <b>Image</b> and <b>Feedback</b>. Design and arrange this component as well as possible. Route path: <code>/student/:id</code></p></div><div class=\"ml-vi\"><p><b>Câu 5 (1,5 điểm)</b> — <b>Task 2, Q5</b>: Ở route <b>detail</b>, hiện đủ thông tin: <b>Id</b>, <b>Name</b>, <b>DateOfBirth</b>, <b>Gender</b>, <b>Class</b>, <b>Image</b> và <b>Feedback</b>, trình bày đẹp nhất có thể. Đường dẫn: <code>/student/:id</code></p></div>",
          "sampleSolution": "<div class=\"ml-en\"><pre><code>// src/pages/StudentDetail.js\nimport { useEffect, useState } from \"react\";\nimport { useParams, Link } from \"react-router-dom\";\nimport { Card, Row, Col, Image, Table, Button, Alert } from \"react-bootstrap\";\nimport { getStudent, genderText } from \"../api\";\n\n// Q5 — /student/:id shows every field, including Feedback\nexport default function StudentDetail() {\n  const { id } = useParams();\n  const [student, setStudent] = useState(null);\n  const [error, setError] = useState(\"\");\n\n  useEffect(() =&gt; {\n    getStudent(id).then(setStudent).catch(() =&gt; setError(\"Student not found\"));\n  }, [id]);\n\n  if (error) return &lt;Alert variant=\"warning\"&gt;{error}&lt;/Alert&gt;;\n  if (!student) return &lt;p&gt;Loading...&lt;/p&gt;;\n\n  return (\n    &lt;Card className=\"mx-auto\" style={{ maxWidth: 720 }}&gt;\n      &lt;Card.Header as=\"h4\"&gt;Student Detail&lt;/Card.Header&gt;\n      &lt;Card.Body&gt;\n        &lt;Row className=\"align-items-center\"&gt;\n          &lt;Col md={4} className=\"text-center\"&gt;\n            &lt;Image src={student.image} alt={student.name} roundedCircle width={160} height={160} /&gt;\n          &lt;/Col&gt;\n          &lt;Col md={8}&gt;\n            &lt;Table borderless size=\"sm\" className=\"mb-0\"&gt;\n              &lt;tbody&gt;\n                &lt;tr&gt;&lt;th&gt;Id&lt;/th&gt;&lt;td&gt;{student.id}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;td&gt;{student.name}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;DateOfBirth&lt;/th&gt;&lt;td&gt;{student.dateofbirth}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Gender&lt;/th&gt;&lt;td&gt;{genderText(student.gender)}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Class&lt;/th&gt;&lt;td&gt;{student.class}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Feedback&lt;/th&gt;&lt;td&gt;{student.feedback}&lt;/td&gt;&lt;/tr&gt;\n              &lt;/tbody&gt;\n            &lt;/Table&gt;\n          &lt;/Col&gt;\n        &lt;/Row&gt;\n      &lt;/Card.Body&gt;\n      &lt;Card.Footer&gt;&lt;Button as={Link} to=\"/\" variant=\"secondary\" size=\"sm\"&gt;Back to Home&lt;/Button&gt;&lt;/Card.Footer&gt;\n    &lt;/Card&gt;\n  );\n}</code></pre><p><code>useParams</code> → <code>GET /studentManagement/:id</code>; every field incl. Feedback.</p></div><div class=\"ml-vi\"><pre><code>// src/pages/StudentDetail.js\nimport { useEffect, useState } from \"react\";\nimport { useParams, Link } from \"react-router-dom\";\nimport { Card, Row, Col, Image, Table, Button, Alert } from \"react-bootstrap\";\nimport { getStudent, genderText } from \"../api\";\n\n// Q5 — /student/:id shows every field, including Feedback\nexport default function StudentDetail() {\n  const { id } = useParams();\n  const [student, setStudent] = useState(null);\n  const [error, setError] = useState(\"\");\n\n  useEffect(() =&gt; {\n    getStudent(id).then(setStudent).catch(() =&gt; setError(\"Student not found\"));\n  }, [id]);\n\n  if (error) return &lt;Alert variant=\"warning\"&gt;{error}&lt;/Alert&gt;;\n  if (!student) return &lt;p&gt;Loading...&lt;/p&gt;;\n\n  return (\n    &lt;Card className=\"mx-auto\" style={{ maxWidth: 720 }}&gt;\n      &lt;Card.Header as=\"h4\"&gt;Student Detail&lt;/Card.Header&gt;\n      &lt;Card.Body&gt;\n        &lt;Row className=\"align-items-center\"&gt;\n          &lt;Col md={4} className=\"text-center\"&gt;\n            &lt;Image src={student.image} alt={student.name} roundedCircle width={160} height={160} /&gt;\n          &lt;/Col&gt;\n          &lt;Col md={8}&gt;\n            &lt;Table borderless size=\"sm\" className=\"mb-0\"&gt;\n              &lt;tbody&gt;\n                &lt;tr&gt;&lt;th&gt;Id&lt;/th&gt;&lt;td&gt;{student.id}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;td&gt;{student.name}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;DateOfBirth&lt;/th&gt;&lt;td&gt;{student.dateofbirth}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Gender&lt;/th&gt;&lt;td&gt;{genderText(student.gender)}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Class&lt;/th&gt;&lt;td&gt;{student.class}&lt;/td&gt;&lt;/tr&gt;\n                &lt;tr&gt;&lt;th&gt;Feedback&lt;/th&gt;&lt;td&gt;{student.feedback}&lt;/td&gt;&lt;/tr&gt;\n              &lt;/tbody&gt;\n            &lt;/Table&gt;\n          &lt;/Col&gt;\n        &lt;/Row&gt;\n      &lt;/Card.Body&gt;\n      &lt;Card.Footer&gt;&lt;Button as={Link} to=\"/\" variant=\"secondary\" size=\"sm\"&gt;Back to Home&lt;/Button&gt;&lt;/Card.Footer&gt;\n    &lt;/Card&gt;\n  );\n}</code></pre><p><code>useParams</code> → <code>GET /studentManagement/:id</code>; đủ mọi trường kể cả Feedback.</p></div>",
