          "prompt": "<div class=\"ml-en\"><p><b>Question 9 (1.5 points)</b> — <b>Task 3, Q9</b>: Implement the <i>update</i> action. The <i>update</i> function must follow the same validation requirements as the <i>add</i> function.</p></div><div class=\"ml-vi\"><p><b>Câu 9 (1,5 điểm)</b> — <b>Task 3, Q9</b>: Làm chức năng <i>cập nhật</i>; phải kiểm tra hợp lệ y như chức năng thêm.</p></div>",
          "sampleSolution": "<div class=\"ml-en\"><pre><code>// src/pages/EditStudent.js\nimport { useEffect, useState } from \"react\";\nimport { useNavigate, useParams } from \"react-router-dom\";\nimport { Card } from \"react-bootstrap\";\nimport StudentForm, { toForm } from \"../components/StudentForm\";\nimport { getStudent, updateStudent } from \"../api\";\n\n// Q9 — /editStudent/:id : same form + same validation, pre-filled, PUT\nexport default function EditStudent() {\n  const { id } = useParams();\n  const navigate = useNavigate();\n  const [initial, setInitial] = useState(null);\n\n  useEffect(() =&gt; {\n    getStudent(id).then((s) =&gt; setInitial(toForm(s)));\n  }, [id]);\n\n  const save = async (student) =&gt; {\n    await updateStudent(id, { ...student, id });\n    navigate(\"/management\", { state: { notice: \"Student updated successfully!\" } });\n  };\n\n  if (!initial) return &lt;p&gt;Loading...&lt;/p&gt;;\n  return (\n    &lt;Card&gt;\n      &lt;Card.Header as=\"h4\"&gt;Update Student #{id}&lt;/Card.Header&gt;\n      &lt;Card.Body&gt;\n        &lt;StudentForm initial={initial} submitText=\"Update\" onSubmit={save} onCancel={() =&gt; navigate(\"/management\")} /&gt;\n      &lt;/Card.Body&gt;\n    &lt;/Card&gt;\n  );\n}</code></pre><p><code>/editStudent/:id</code> pre-fills the same form (<code>toForm</code>), validates with the same <code>validate()</code>, then <code>PUT</code>s and returns to /management with a notice.</p></div><div class=\"ml-vi\"><pre><code>// src/pages/EditStudent.js\nimport { useEffect, useState } from \"react\";\nimport { useNavigate, useParams } from \"react-router-dom\";\nimport { Card } from \"react-bootstrap\";\nimport StudentForm, { toForm } from \"../components/StudentForm\";\nimport { getStudent, updateStudent } from \"../api\";\n\n// Q9 — /editStudent/:id : same form + same validation, pre-filled, PUT\nexport default function EditStudent() {\n  const { id } = useParams();\n  const navigate = useNavigate();\n  const [initial, setInitial] = useState(null);\n\n  useEffect(() =&gt; {\n    getStudent(id).then((s) =&gt; setInitial(toForm(s)));\n  }, [id]);\n\n  const save = async (student) =&gt; {\n    await updateStudent(id, { ...student, id });\n    navigate(\"/management\", { state: { notice: \"Student updated successfully!\" } });\n  };\n\n  if (!initial) return &lt;p&gt;Loading...&lt;/p&gt;;\n  return (\n    &lt;Card&gt;\n      &lt;Card.Header as=\"h4\"&gt;Update Student #{id}&lt;/Card.Header&gt;\n      &lt;Card.Body&gt;\n        &lt;StudentForm initial={initial} submitText=\"Update\" onSubmit={save} onCancel={() =&gt; navigate(\"/management\")} /&gt;\n      &lt;/Card.Body&gt;\n    &lt;/Card&gt;\n  );\n}</code></pre><p><code>/editStudent/:id</code> nạp sẵn cùng form (<code>toForm</code>), kiểm bằng cùng <code>validate()</code>, rồi <code>PUT</code> và quay về /management kèm thông báo.</p></div>",
